namespace Workbench.Application.Collaboration;

/// <summary>
/// Stores attachment bytes by key. Keys are generated by the application (<c>{sheet}/{attachment}</c>),
/// never taken from user input. The dev implementation writes to local disk; deployments can swap in
/// object storage.
/// </summary>
public interface IBlobStore
{
    /// <summary>Writes <paramref name="content"/> under <paramref name="key"/>, replacing any existing blob, and returns the byte count.</summary>
    Task<long> SaveAsync(string key, Stream content, CancellationToken cancellationToken = default);

    /// <summary>Opens a blob for reading. Throws <see cref="FileNotFoundException"/> when it doesn't exist.</summary>
    Task<Stream> OpenReadAsync(string key, CancellationToken cancellationToken = default);

    /// <summary>Deletes a blob. Missing blobs are ignored.</summary>
    Task DeleteAsync(string key, CancellationToken cancellationToken = default);
}
